#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int totalCount, btcBudget;
    std::cin >> totalCount >> btcBudget;
    std::vector<int> btcDiffsArray(100, 0);
    int evenCount = 0, oddCount = 0;
    int storedRightValue = 0;

    for (int index = 0; index < totalCount; index++) {
        int currentLeftValue = 0;
        if (storedRightValue == 0) {
            std::cin >> currentLeftValue;
        } else {
            currentLeftValue = storedRightValue;
            storedRightValue = 0;
        }

        if (currentLeftValue % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (evenCount == oddCount && index != totalCount - 1) {
            int nextValue;
            std::cin >> nextValue;
            storedRightValue = nextValue;
            int diff = std::abs(currentLeftValue - storedRightValue);
            if (diff < 100) {
                btcDiffsArray[diff] += 1;
            }
            evenCount = 0;
            oddCount = 0;
        }
    }

    int totalSawn = 0;
    int totalCostSum = 0;
    for (int i = 0; i < 100; i++) {
        for (int j = 0; j < btcDiffsArray[i]; j++) {
            totalCostSum += i;
            if (totalCostSum <= btcBudget) {
                totalSawn++;
            } else {
                break;
            }
        }
        if (totalCostSum > btcBudget) {
            break;
        }
    }

    std::cout << totalSawn << std::endl;
    return 0;
}

